$ErrorActionPreference = "Stop"
$project = "C:\Users\Admin\projects\mse\mother-soil-equipments"
Set-Location $project
Write-Host "Updating Mother Soil Equipments..."
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\views\Contact.vue"), $data)
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\views\Products.vue"), $data)
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\views\Subsidy.vue"), $data)
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\components\SiteFooter.vue"), $data)
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\data\company.js"), $data)
$data = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $project "src\data\products.js"), $data)
$cssPath = Join-Path $project "src\assets\styles\main.css"
$css = Get-Content $cssPath -Raw
if ($css -notmatch "Requested contact, product grid, subsidy and footer refinements") {
  $data = [System.Convert]::FromBase64String("")
  $addition = [System.Text.Encoding]::UTF8.GetString($data)
  Add-Content -Path $cssPath -Value $addition -Encoding UTF8
  Write-Host "CSS refinements added."
} else { Write-Host "CSS refinements already present; skipped duplicate append." }
Write-Host ""
Write-Host "Done. Run: npm run dev"
